update newsletter_sequences set steps='[{"subject":"RE : Candidature appartement à louer","preheader":"Recherche, visite, postulation : laissez-nous prendre le relais.","html":"<!DOCTYPE html>\n<html lang=\"fr\" xmlns:v=\"urn:schemas-microsoft-com:vml\" xmlns:w=\"urn:schemas-microsoft-com:office:word\">\n<head><meta charset=\"UTF-8\"><meta name=\"viewport\" content=\"width=device-width, initial-scale=1\"><meta name=\"color-scheme\" content=\"light\"><title>RE : Candidature appartement à louer</title>\n<style>@media screen and (max-width:520px){.outer{padding:0!important}.pad{padding-left:24px!important;padding-right:24px!important}.heading{font-size:30px!important;line-height:33px!important}.col{display:block!important;width:100%!important;box-sizing:border-box!important}.coltext{padding:24px 0 0!important}.section{padding:28px 24px!important}.brandline{font-size:9px!important;letter-spacing:1px!important}}</style></head>\n<body style=\"margin:0;background:#eef0eb;font-family:Arial,Helvetica,sans-serif;\">\n<div id=\"newsletter-preheader\" style=\"display:none;font-size:1px;line-height:1px;max-height:0;max-width:0;opacity:0;overflow:hidden;mso-hide:all;\">Recherche, visite, postulation : laissez-nous prendre le relais.</div>\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" bgcolor=\"#eef0eb\"><tr><td align=\"center\" class=\"outer\" style=\"padding:24px 12px;\">\n<!--[if mso]><table role=\"presentation\" width=\"640\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr><td><![endif]-->\n<table id=\"newsletter\" role=\"presentation\" width=\"640\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" bgcolor=\"#ffffff\" style=\"width:100%;max-width:640px;border-top:4px solid #205a43;\">\n<tr><td class=\"pad\" style=\"padding:20px 36px;\">\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr><td>\n<div style=\"font-size:27px;line-height:30px;font-weight:bold;letter-spacing:-1px;color:#193d2c;\">Logisorama</div>\n<img src=\"https://logisorama.ch/__l5e/assets-v1/620cc5b1-18df-42ab-86d6-2ea17731daef/logisorama-email-logo.png\" width=\"144\" height=\"40\" alt=\"Logisorama\" style=\"display:block;border:0;margin-top:3px;\">\n</td><td align=\"right\" class=\"brandline\" style=\"font-size:10px;line-height:17px;letter-spacing:1.5px;color:#677a6c;\">LA NEWSLETTER<br>VOTRE CANDIDATURE</td></tr></table>\n</td></tr>\n<tr><td style=\"padding:0;\"><a href=\"https://logisorama.ch/nouveau-mandat\" target=\"_blank\"><img src=\"https://logisorama.ch/newsletter/candidature-hero.jpg\" width=\"640\" alt=\"Une femme consulte son téléphone, accompagnée d’une enveloppe, d’une maison et d’une étoile en 3D.\" style=\"display:block;border:0;width:100%;height:auto;\"></a></td></tr>\n<tr><td class=\"pad\" style=\"padding:28px 36px 32px;\"><div style=\"margin-bottom:9px;font-size:11px;line-height:18px;letter-spacing:1.5px;font-weight:bold;color:#73816e;\">VOTRE RECHERCHE DE LOGEMENT</div><h1 class=\"heading\" style=\"margin:0 0 16px;color:#1c523c;font-size:36px;line-height:39px;letter-spacing:-1.1px;\">Toujours sans réponse<br>de la gérance ?</h1><p style=\"margin:0 0 18px;font-size:16px;line-height:25px;color:#5c665e;\">Vous attendez encore une réponse de la gérance pour un logement que vous avez visité ?</p><p style=\"margin:0 0 18px;font-size:16px;line-height:25px;color:#5c665e;\">Laissez-nous prendre le relais pour augmenter vos chances de trouver l’appartement qui correspond vraiment à vos critères.</p><a href=\"https://logisorama.ch/nouveau-mandat\" target=\"_blank\" style=\"display:inline-block;background:#205a43;border:1px solid #205a43;border-radius:5px;color:#ffffff;font:700 16px/22px Arial,sans-serif;padding:14px 20px;text-decoration:none;text-align:center;\">Activer ma recherche en 5 minutes &rarr;</a></td></tr>\n<tr><td class=\"pad\" style=\"padding:26px 36px 0;border-top:1px solid #e7ebe5;\"><div style=\"margin-bottom:9px;font-size:11px;line-height:18px;letter-spacing:1.5px;font-weight:bold;color:#73816e;\">LOGISORAMA VOUS ACCOMPAGNE</div><h2 style=\"margin:0;font-size:27px;line-height:33px;color:#243c2c;\">On s’occupe de tout,<br>de A à Z.</h2></td></tr>\n<tr><td class=\"section\" style=\"padding:26px 36px 30px;\"><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr><td class=\"col\" width=\"47%\" valign=\"middle\"><img src=\"https://logisorama.ch/newsletter/candidature-parcours.jpg\" width=\"267\" alt=\"Une maison, une loupe, une clé et un dossier vert illustrent la recherche, la visite et la postulation.\" style=\"display:block;border:0;width:100%;height:auto;\"></td><td class=\"col coltext\" width=\"53%\" valign=\"middle\" style=\"padding-left:26px;\"><div style=\"margin-bottom:9px;font-size:11px;line-height:18px;letter-spacing:1.5px;font-weight:bold;color:#73816e;\">01 &nbsp; RECHERCHE</div><p style=\"margin:0 0 20px;color:#60695f;font-size:15px;line-height:23px;\">Des appartements qui correspondent à vos critères.</p><div style=\"margin-bottom:9px;font-size:11px;line-height:18px;letter-spacing:1.5px;font-weight:bold;color:#73816e;\">02 &nbsp; VISITE</div><p style=\"margin:0 0 20px;color:#60695f;font-size:15px;line-height:23px;\">Nous prenons le relais pour vos visites.</p><div style=\"margin-bottom:9px;font-size:11px;line-height:18px;letter-spacing:1.5px;font-weight:bold;color:#73816e;\">03 &nbsp; POSTULATION</div><p style=\"margin:0 0 20px;color:#60695f;font-size:15px;line-height:23px;\">Nous vous accompagnons dans vos candidatures.</p></td></tr></table></td></tr>\n<tr><td class=\"pad\" style=\"padding:34px 36px;background:#1c4734;color:#fff;text-align:center;\"><div style=\"color:#d8ddc9;font-size:10px;line-height:16px;letter-spacing:2px;\">VOTRE PROCHAINE ÉTAPE</div><h2 style=\"margin:9px 0 12px;font-size:27px;line-height:33px;\">Activez votre recherche<br>en 5 minutes.</h2><p style=\"margin:0 0 22px;font-size:15px;line-height:24px;color:#e0e7da;\">Indiquez vos critères et laissez-nous prendre le relais.</p><a href=\"https://logisorama.ch/nouveau-mandat\" target=\"_blank\" style=\"display:inline-block;background:#f4eddd;border:1px solid #f4eddd;border-radius:5px;color:#194633;font:700 16px/22px Arial,sans-serif;padding:14px 20px;text-decoration:none;text-align:center;\">Activer ma recherche &rarr;</a></td></tr>\n<tr><td align=\"center\" style=\"padding:26px 24px;color:#7b847a;font-size:12px;line-height:20px;\"><strong style=\"color:#435b47;\">Logisorama · Immo-rama</strong><br>Votre recherche de logement, au même endroit.<br><a href=\"{{unsubscribe_url}}\" style=\"color:#7b847a\">Se désinscrire</a></td></tr>\n</table>\n<!--[if mso]></td></tr></table><![endif]-->\n</td></tr></table></body></html>"},{"subject":"Votre recherche de location — Faisons le point sur votre projet","preheader":"Votre projet est-il toujours d’actualité ? Vous pouvez compléter votre demande ou reprendre contact avec notre équipe.","html":"<!DOCTYPE html><html lang=\"fr\"><head><meta charset=\"utf-8\"><meta name=\"logisorama-email-layout\" content=\"corporate-v1\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><meta name=\"color-scheme\" content=\"light\"><title>Faisons le point sur votre projet</title><style>@media screen and (max-width:520px){.email-stack{display:block!important;width:100%!important;padding-left:0!important;padding-right:0!important;box-sizing:border-box!important}.email-outer{padding:0!important}.email-pad{padding-left:24px!important;padding-right:24px!important}.email-heading{font-size:26px!important;line-height:32px!important}.email-brandline{font-size:9px!important;letter-spacing:.7px!important}}</style></head>\n<body style=\"margin:0;padding:0;background:#eef0eb;font-family:Arial,Helvetica,sans-serif;\">\n<div style=\"display:none;font-size:1px;line-height:1px;max-height:0;max-width:0;opacity:0;overflow:hidden;mso-hide:all;\">Faisons le point sur votre projet</div>\n<table role=\"presentation\" width=\"100%\" c